// @ts-check
import { antfu } from '@antfu/eslint-config'

export default antfu().append(
  {
    ignores: ['benchmark/**', 'example/app*.js'],
  },
)

import { defineConfig } from 'vitest/config'

export default defineConfig({
  define: {
    DEBUG: 'true',
  },
  test: {
    environment: 'node',
    isolate: false,
    coverage: {
      exclude: [
        'src/**/*.test.ts',
        'tests/**',
        'dist/**',
      ],
    },
  },
})

import { defineConfig } from 'vitest/config';

const excludePrivateIntegration =
	!process.env.SSH_PRIVATE_KEY || process.env.SSH_PRIVATE_KEY === ''
		? ['test/integration/private.test.ts']
		: undefined;

export default defineConfig({
	test: {
		coverage: {
			all: true,
			include: ['src/**/*.ts'],
			provider: 'v8',
			reporter: ['text', 'json-summary', 'html'],
			reportsDirectory: './coverage',
			thresholds: {
				autoUpdate: false,
				branches: 50,
				functions: 50,
				lines: 40,
				statements: 40,
			},
		},
		environment: 'node',
		exclude: excludePrivateIntegration,
		globals: true,
		include: ['test/**/*.test.ts'],
		testTimeout: 30000,
	},
});

{
  "name": "svg-parser",
  "version": "2.1.0",
  "description": "Create a JSON-friendly object from an SVG string",
  "main": "dist/svg-parser.umd.js",
  "jsnext:main": "dist/svg-parser.esm.js",
  "module": "dist/svg-parser.esm.js",
  "files": [
    "dist",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "test": "mocha",
    "build": "tsdown",
    "pretest": "npm run build",
    "prepublishOnly": "npm run lint && npm test",
    "lint": "oxlint src && oxfmt --check .",
    "format": "oxfmt --write ."
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Rich-Harris/svg-parser.git"
  },
  "keywords": [
    "SVG",
    "parser",
    "JSON",
    "object"
  ],
  "author": "Rich Harris",
  "contributors": [
    {
      "name": "Bogdan Chadkin",
      "email": "opensource@trysound.io"
    }
  ],
  "license": "MIT",
  "engines": {
    "node": ">=8"
  },
  "tsdown": {
    "entry": {
      "svg-parser": "src/index.js"
    },
    "format": {
      "esm": {
        "outputOptions": {
          "entryFileNames": "[name].esm.js"
        }
      },
      "umd": {
        "globalName": "svgParser",
        "outputOptions": {
          "entryFileNames": "[name].umd.js"
        }
      }
    },
    "platform": "browser",
    "target": "es2015",
    "deps": {
      "onlyBundle": [
        "locate-character"
      ]
    },
    "sourcemap": true
  },
  "bugs": {
    "url": "https://github.com/Rich-Harris/svg-parser/issues"
  },
  "homepage": "https://github.com/Rich-Harris/svg-parser#README",
  "overrides": {
    "debug": "3.2.7",
    "diff": "3.5.1",
    "js-yaml": "3.15.1",
    "minimatch": "3.1.4"
  },
  "devDependencies": {
    "locate-character": "^2.0.5",
    "mocha": "^7.2.0",
    "oxfmt": "^0.64.0",
    "oxlint": "^1.79.0",
    "source-map-support": "^0.4.2",
    "tsdown": "^0.22.14"
  }
}

{
	"name": "periscopic",
	"description": "periscopic",
	"version": "4.0.3",
	"repository": {
		"type": "git",
		"url": "https://github.com/Rich-Harris/periscopic"
	},
	"main": "src/index.js",
	"module": "src/index.js",
	"type": "module",
	"exports": {
		"types": "./types/index.js",
		"default": "./src/index.js"
	},
	"types": "types/index.d.ts",
	"files": [
		"src",
		"types"
	],
	"devDependencies": {
		"@changesets/cli": "^2.31.0",
		"acorn": "^8.10.0",
		"dts-buddy": "^0.2.4",
		"typescript": "^5.2.2",
		"uvu": "^0.5.6"
	},
	"scripts": {
		"test": "uvu test",
		"prepublishOnly": "npm test && dts-buddy",
		"changeset:version": "changeset version",
		"changeset:publish": "changeset publish"
	},
	"license": "MIT",
	"dependencies": {
		"@types/estree": "*",
		"is-reference": "^3.0.2",
		"zimmerframe": "^1.0.0"
	},
	"packageManager": "pnpm@10.33.0",
	"publishConfig": {
		"access": "public"
	}
}

