{
	"name": "estree-walker",
	"description": "Traverse an ESTree-compliant AST",
	"version": "3.0.3",
	"private": false,
	"author": "Rich Harris",
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "https://github.com/Rich-Harris/estree-walker"
	},
	"type": "module",
	"module": "./src/index.js",
	"exports": {
		"./package.json": "./package.json",
		".": {
			"types": "./types/index.d.ts",
			"import": "./src/index.js"
		}
	},
	"types": "types/index.d.ts",
	"scripts": {
		"prepublishOnly": "tsc && npm test",
		"test": "uvu test"
	},
	"dependencies": {
		"@types/estree": "^1.0.0"
	},
	"devDependencies": {
		"typescript": "^4.9.0",
		"uvu": "^0.5.1"
	},
	"files": [
		"src",
		"types",
		"README.md"
	]
}

{
    "rules": {
        "indent": [ 2, "tab", { "SwitchCase": 1 } ],
        "quotes": [ 2, "single" ],
        "linebreak-style": [ 2, "unix" ],
        "semi": [ 2, "always" ],
        "keyword-spacing": [ 2, { "before": true, "after": true } ],
        "space-before-blocks": [ 2, "always" ],
        "space-before-function-paren": [ 2, "always" ],
        "no-mixed-spaces-and-tabs": [ 2, "smart-tabs" ],
        "no-cond-assign": [ 0 ]
    },
    "env": {
        "es6": true,
        "browser": true,
        "mocha": true,
        "node": true
    },
    "extends": "eslint:recommended",
    "parserOptions": {
        "ecmaVersion": 6,
        "sourceType": "module"
    }
}

{
	"useTabs": true,
	"singleQuote": true,
	"trailingComma": "none",
	"printWidth": 100
}

