{
	"type": "module",
	"dependencies": {
		"vite": "^5.3.1"
	},
	"scripts": {
		"build": "vite build"
	}
}

import { defineConfig } from 'vite';

export default defineConfig({
	build: {
		assetsInlineLimit: 0,
		rollupOptions: {
			input: {
				a: 'src/a.js',
				b: 'src/b.js',
				c: 'src/c.js'
			},
			output: {
				assetFileNames: 'assets/[name][extname]',
				entryFileNames: '[name].js',
				chunkFileNames: 'chunks/[name].js'
			}
		},
		manifest: true,
		minify: false,
		target: 'esnext'
	}
});

{
	"name": "sorcery",
	"description": "Resolve a chain of sourcemaps back to the original source",
	"version": "1.0.0",
	"author": "Rich Harris",
	"repository": "https://github.com/Rich-Harris/sorcery",
	"type": "module",
	"exports": {
		".": {
			"types": "./types/index.d.ts",
			"default": "./src/index.js"
		}
	},
	"license": "MIT",
	"dependencies": {
		"@jridgewell/sourcemap-codec": "^1.4.14",
		"minimist": "^1.2.0",
		"tiny-glob": "^0.2.9"
	},
	"devDependencies": {
		"@types/node": "^20.14.2",
		"coffee-script": "^1.10.0",
		"less": "^2.6.1",
		"prettier": "^3.3.2",
		"rimraf": "^5.0.7",
		"source-map": "^0.5.3",
		"typescript": "^5.4.5",
		"uglify-js": "^2.6.2"
	},
	"bin": {
		"sorcery": "bin/sorcery"
	},
	"scripts": {
		"build": "tsc",
		"prepare-tests": "node test/samples/prepare-tests.js",
		"prepublishOnly": "pnpm test && pnpm build",
		"lint": "prettier .",
		"format": "prettier --write .",
		"test": "node test/sorcery.test.js"
	},
	"files": [
		"src/",
		"bin/",
		"README.md"
	],
	"packageManager": "pnpm@9.3.0"
}

{
	"useTabs": true,
	"semi": true,
	"singleQuote": true,
	"trailingComma": "none",
	"overrides": [
		{
			"files": "*.md",
			"options": {
				"useTabs": false
			}
		}
	]
}

